<script lang="ts">
import { defineComponent } from 'vue';
import { deleteReaderAccount, issueReaderPasswordReset, listReaderAccounts, setReaderEnabled, type AdminReaderAccount, type PasswordResetCredential } from '../../api/auth';
import AppButton from '../../ui/components/AppButton.vue';
import FeatureScaffold from '../../ui/components/FeatureScaffold.vue';
import ReaderDeleteDialog from './ReaderDeleteDialog.vue';
import ReaderResetDialog from './ReaderResetDialog.vue';
import { filterReaderAccounts, readerCounts, replaceReaderAccount, type ReaderStatusFilter } from './reader-administration';
export default defineComponent({
  name:'ReaderAdministrationView',components:{AppButton,FeatureScaffold,ReaderDeleteDialog,ReaderResetDialog},
  data(){return{accounts:[] as AdminReaderAccount[],loading:true,error:'',notice:'',query:'',status:'all' as ReaderStatusFilter,busyID:'',resetAccount:null as AdminReaderAccount|null,credential:null as PasswordResetCredential|null,resetError:'',deleteAccount:null as AdminReaderAccount|null,deleteError:''}},
  computed:{filtered():AdminReaderAccount[]{return filterReaderAccounts(this.accounts,this.query,this.status)},counts(){return readerCounts(this.accounts)}},
  async mounted(){await this.load()},
  methods:{
    async load(){this.loading=true;this.error='';try{this.accounts=await listReaderAccounts()}catch(cause){this.error=cause instanceof Error?cause.message:this.$t('account.readers.loadFailed')}finally{this.loading=false}},
    formatDate(value:number){return new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(value*1000))},
    openReset(account:AdminReaderAccount){this.resetAccount=account;this.credential=null;this.resetError=''},
    closeReset(){if(this.busyID)return;this.resetAccount=null;this.credential=null;this.resetError=''},
    async issueReset(){if(!this.resetAccount||this.busyID)return;this.busyID=this.resetAccount.id;this.resetError='';try{this.credential=await issueReaderPasswordReset(this.resetAccount.id)}catch(cause){this.resetError=cause instanceof Error?cause.message:this.$t('account.readers.reset.failed')}finally{this.busyID=''}},
    async toggle(account:AdminReaderAccount){if(this.busyID||account.status==='deleting')return;this.busyID=account.id;this.error='';try{const updated=await setReaderEnabled(account.id,account.status!=='active');this.accounts=replaceReaderAccount(this.accounts,updated);this.notice=this.$t(updated.status==='active'?'account.readers.notice.enabled':'account.readers.notice.disabled',{username:updated.username})}catch(cause){this.error=cause instanceof Error?cause.message:this.$t('account.readers.statusFailed')}finally{this.busyID=''}},
    openDelete(account:AdminReaderAccount){this.deleteAccount=account;this.deleteError=''},
    closeDelete(){if(this.busyID)return;this.deleteAccount=null;this.deleteError=''},
    async confirmDelete(username:string){if(!this.deleteAccount||this.busyID)return;const target=this.deleteAccount;this.busyID=target.id;this.deleteError='';try{await deleteReaderAccount(target.id,username);this.accounts=this.accounts.filter(account=>account.id!==target.id);this.deleteAccount=null;this.notice=this.$t('account.readers.notice.deleted',{username:target.username})}catch(cause){this.deleteError=cause instanceof Error?cause.message:this.$t('account.readers.delete.failed');await this.load().catch(()=>undefined);this.deleteAccount=this.accounts.find(account=>account.id===target.id)??target}finally{this.busyID=''}},
  }
});
</script>
<template><FeatureScaffold :title="$t('account.readers.title')" :description="$t('account.readers.description')"><div class="page"><section class="toolbar"><div class="stats"><strong>{{ $t('account.readers.stats.total',{count:counts.total}) }}</strong><span>{{ $t('account.readers.stats.active',{count:counts.active}) }}</span><span>{{ $t('account.readers.stats.disabled',{count:counts.disabled}) }}</span><span v-if="counts.deleting">{{ $t('account.readers.stats.deleting',{count:counts.deleting}) }}</span></div><AppButton variant="secondary" :busy="loading" @click="load">{{ $t('account.readers.refresh') }}</AppButton></section><section class="filters"><label><span>{{ $t('account.readers.search') }}</span><input v-model="query" type="search" :placeholder="$t('account.readers.searchPlaceholder')"></label><label><span>{{ $t('account.readers.filter') }}</span><select v-model="status"><option value="all">{{ $t('account.readers.filters.all') }}</option><option value="active">{{ $t('account.readers.filters.active') }}</option><option value="disabled">{{ $t('account.readers.filters.disabled') }}</option><option value="deleting">{{ $t('account.readers.filters.deleting') }}</option></select></label></section><p v-if="notice" class="notice" role="status">{{ notice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" aria-busy="true">{{ $t('account.readers.loading') }}</p><section v-else-if="!accounts.length" class="empty"><h2>{{ $t('account.readers.empty.title') }}</h2><p>{{ $t('account.readers.empty.description') }}</p></section><section v-else-if="!filtered.length" class="empty"><h2>{{ $t('account.readers.empty.filteredTitle') }}</h2><p>{{ $t('account.readers.empty.filteredDescription') }}</p></section><ul v-else class="reader-list"><li v-for="account in filtered" :key="account.id"><div class="identity"><div class="name"><strong>{{ account.username }}</strong><span :class="`status status-${account.status}`">{{ $t(`account.readers.status.${account.status}`) }}</span></div><small>{{ account.id }}</small><p>{{ $t('account.readers.created',{date:formatDate(account.createdAt)}) }} · {{ $t('account.readers.updated',{date:formatDate(account.updatedAt)}) }}</p></div><div class="actions"><AppButton v-if="account.status!=='deleting'" variant="secondary" :busy="busyID===account.id" @click="toggle(account)">{{ account.status==='active'?$t('account.readers.disable'):$t('account.readers.enable') }}</AppButton><AppButton v-if="account.status!=='deleting'" variant="quiet" :disabled="Boolean(busyID)" @click="openReset(account)">{{ $t('account.readers.reset.action') }}</AppButton><AppButton variant="danger" :disabled="Boolean(busyID)" @click="openDelete(account)">{{ account.status==='deleting'?$t('account.readers.delete.retry'):$t('account.readers.delete.action') }}</AppButton></div></li></ul></div><ReaderResetDialog v-if="resetAccount" :account="resetAccount" :credential="credential" :busy="busyID===resetAccount.id" :error="resetError" @issue="issueReset" @close="closeReset" /><ReaderDeleteDialog v-if="deleteAccount" :account="deleteAccount" :busy="busyID===deleteAccount.id" :error="deleteError" @confirm="confirmDelete" @close="closeDelete" /></FeatureScaffold></template>
<style scoped>.page{display:grid;gap:1rem}.toolbar,.filters{display:flex;justify-content:space-between;align-items:center;gap:1rem}.stats{display:flex;flex-wrap:wrap;gap:.45rem}.stats strong,.stats span{border-radius:999px;padding:.35rem .65rem;background:var(--color-paper-muted);font-size:.78rem}.filters{padding:1rem;border:1px solid var(--color-border);border-radius:var(--radius-lg);background:var(--color-paper-raised)}.filters label{min-width:0;flex:1;display:grid;gap:.3rem}.filters label:last-child{max-width:18rem}.filters span{color:var(--color-ink-muted);font-size:.78rem;font-weight:700}.filters input,.filters select{min-height:2.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md);padding:.55rem .7rem;background:white;color:var(--color-ink)}.notice,.error{margin:0;padding:.7rem;border-radius:var(--radius-md)}.notice{background:#e7efe8;color:var(--color-success)}.error{background:#f8e4df;color:var(--color-danger)}.empty{padding:2.5rem 1rem;border:1px dashed var(--color-border);border-radius:var(--radius-lg);text-align:center}.empty h2{font:700 1.2rem var(--font-literary)}.empty p{color:var(--color-ink-muted)}.reader-list{list-style:none;display:grid;gap:.65rem;margin:0;padding:0}.reader-list li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:1rem;align-items:center;padding:1rem;border:1px solid var(--color-border);border-radius:var(--radius-lg);background:var(--color-paper-raised)}.identity{min-width:0}.name{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem}.identity small,.identity p{display:block;margin:.25rem 0 0;color:var(--color-ink-muted);overflow-wrap:anywhere}.status{border-radius:999px;padding:.2rem .45rem;font-size:.7rem;font-weight:800}.status-active{background:#e7efe8;color:var(--color-success)}.status-disabled{background:var(--color-paper-muted);color:var(--color-ink-muted)}.status-deleting{background:#f8e4df;color:var(--color-danger)}.actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:.4rem}@media(max-width:48rem){.toolbar{align-items:stretch;flex-direction:column}.filters{align-items:stretch;flex-direction:column}.filters label:last-child{max-width:none}.reader-list li{grid-template-columns:1fr}.actions{justify-content:flex-start}}@media(max-width:30rem){.actions{display:grid;grid-template-columns:1fr}.actions :deep(.app-button){width:100%}}</style>
